    parsed = urlsplit(url)
    scheme = parsed.scheme.lower()
    host = (parsed.hostname or "").lower()
    port = parsed.port

    if port is not None and (
        (scheme == "http" and port == 80)
        or (scheme == "https" and port == 443)
    ):
        port = None

    if ":" in host and not host.startswith("["):
        authority = f"[{host}]"
    else:
        authority = host
    if port is not None:
        authority = f"{authority}:{port}"

    query_pairs = [
        (name, value)
        for name, value in parse_qsl(parsed.query, keep_blank_values=True)
        if not name.startswith("utm_")
    ]
    query_pairs.sort()
    normalized_query = urlencode(query_pairs)

    normalized_url = urlunsplit(
        (scheme, authority, parsed.path, normalized_query, "")
    )

    relevant_headers = sorted(
        (name.lower(), value.strip())
        for name, value in headers.items()
        if name.lower() in {"accept", "accept-language"}
    )

    normalized = (method.upper(), normalized_url, tuple(relevant_headers))
    return json.dumps(normalized, ensure_ascii=False, separators=(",", ":"))
