from __future__ import annotations

import json
from collections.abc import Mapping
from urllib.parse import parse_qsl, urlencode, urlsplit, urlunsplit


def canonical_cache_key(method: str, url: str, headers: Mapping[str, str]) -> str:
    """Return a stable JSON cache key for the request's cache-varying fields."""
    parts = urlsplit(url)
    scheme = parts.scheme.lower()
    host = (parts.hostname or "").lower()
    # Normalize internationalized host names when possible.
    try:
        host = host.encode("idna").decode("ascii")
    except UnicodeError:
        pass

    port = parts.port
    if port is not None and not (
        (scheme == "http" and port == 80)
        or (scheme == "https" and port == 443)
    ):
        authority = f"{host}:{port}"
    else:
        authority = host
    if ":" in host and not host.startswith("["):
        authority = f"[{authority}]"

    query_items = [
        (key, value)
        for key, value in parse_qsl(parts.query, keep_blank_values=True)
        if not key.lower().startswith("utm_")
    ]
    query = urlencode(sorted(query_items))
    normalized_url = urlunsplit((scheme, authority, parts.path or "/", query, ""))

    selected_headers = {name.lower(): value.strip() for name, value in headers.items()
                        if name.lower() in ("accept", "accept-language")}
    payload = (method.strip().upper(), normalized_url, selected_headers)
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
